int total = 0;              // global: whole program run

void f() {
    int x = 5;              // local: stack, destroyed when f returns
    static int count = 0;   // static: created once, remembers its value
    int *p = new int;       // heap box (next lesson); p itself is on the stack
    *p = 7;
    delete p;               // give the heap box back yourself
}

// Stack:  automatic    | small  | very fast | freed on return
// Heap:   manual (new) | large  | slower    | freed with delete

