#include <iostream>
using namespace std;

int total = 0;

void addOne() {
    int local = 0;
    static int kept = 0;
    local++;
    kept++;
    total++;
    cout << "local = " << local << ", kept = " << kept << ", total = " << total << endl;
}

int main() {
    addOne();
    addOne();
    addOne();
    return 0;
}

#include <iostream>
using namespace std;

void third() {
    int c = 3;
    cout << "third: c = " << c << endl;
}

void second() {
    int b = 2;
    cout << "second: before" << endl;
    third();
    cout << "second: after, b = " << b << endl;
}

void first() {
    int a = 1;
    cout << "first: before" << endl;
    second();
    cout << "first: after, a = " << a << endl;
}

int main() {
    first();
    return 0;
}

#include <iostream>
using namespace std;

int makeCopy() {
    int x = 42;
    return x;
}

int *makeOnHeap() {
    int *p = new int;
    *p = 42;
    return p;
}

void addTen(int *p) {
    *p = *p + 10;
}

int main() {
    int a = makeCopy();
    int *b = makeOnHeap();
    cout << "Copy from the stack: " << a << endl;
    cout << "Value on the heap: " << *b << endl;
    addTen(b);
    cout << "After addTen: " << *b << endl;
    delete b;
    return 0;
}

